command:
if ([...game.combats].filter(combat => combat.isActive).length !== 0)  {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: #C0392B;">Le sort n'est pas utilisable en combat</h3>`
    });
} else if (Number(game.user.character.system.fq.cards.hand) <= 0) {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: #C0392B;">Vous devez avoir un score de main positif</h3>`
    });
} else {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: darkgreen;">Vous préparez vos prochains sorts en piochant votre main, cette action 
peut être considérée comme un acte d'aggression par les personnes autour du joueur</h3>`
    });
    const deck = game.cards.filter(cards => cards.ownership[game.userId] === 3 && cards.type === 'deck')[0];
    const hand = game.cards.filter(cards => cards.ownership[game.userId] === 3 && cards.type === 'hand')[0];
    hand.draw(deck,game.user.character.system.fq.cards.hand, {how: 2})
    game.user.character.createEmbeddedDocuments("ActiveEffect", [
            {
                label: "Dégainer",
                icon: "icons/skills/melee/sword-engraved-glow-purple.webp",
                origin: "FQ Effect",
                changes: [
                    {
                        key: "system.fq.cards.hand",
                        value: "0",
                        mode: 5
                    },
                    {
                        key: "macro.tokenMagic",
                        value: "zoomblur",
                        mode: 0
                    }
                ],
                duration: {
                    startTime: null,
                    rounds: null,
                    turns: null
                },
            }
        ]
    );
    foundry.audio.AudioHelper.play({
        src: "modules/fq-card-engine/sounds/passive_spells/unsheathe.mp3",
        volume: 0.4,
        autoplay: true,
        loop: false
    }, true);
}
